import{beforeAll,afterAll,describe,it,expect}from'vitest';import{randomUUID,createHash}from'node:crypto';import{eq}from'drizzle-orm';import{companies,agents,projects,issues,heartbeatRuns,issueThreadInteractions,completionContracts,nativeRunResults,workAssessments,statusDecisions,createDb}from'@paperclipai/db';
import{startEmbeddedPostgresTestDatabase}from'../../__tests__/helpers/embedded-postgres.js';import{PaperclipRunnerToolAuthority}from'./paperclip-runner-tool-authority.js';import{createAssignedMcpTools}from'./assigned-mcp-tools.js';import{documentService}from'../documents.js';
const raw=['funding_drafting_workspace','save_funding_proposals','save_funding_gap_progress','funding_drafting_checkpoint'].map(x=>'netrxn.inertia:'+x);
const projected=name=>{const sanitize=x=>x.replace(/[^a-zA-Z0-9_]+/g,'_').replace(/^_+|_+$/g,'');const n=name.lastIndexOf(':');return 'app_'+sanitize(name.slice(0,n)).slice(0,20)+'_'+sanitize(name.slice(n+1)).slice(-26)+'_'+createHash('sha256').update(name).digest('hex').slice(0,12);};
describe('restrictive native funding actual authority and assigned gateway intersection',()=>{
 let temporary,db,co,actor,project,issue,run,admitted,calls,assigned;
 const config=()=>({provider:'codex',engine:'cli',disableCommandExecution:true,dangerouslyBypassApprovalsAndSandbox:false,codexPermissionMode:'never',nativeFunding:{version:1,role:'producer',projectIds:[project],issueIds:[issue]}});
 const binding=()=>({companyId:co,agentId:actor,issueId:issue,runId:run,nativeFundingPolicy:{version:1,role:'producer',projectIds:[project],issueIds:[issue],companyId:co,agentId:actor},assignedMcpTools:assigned,connectorAssignments:[{tools:[{name:'synthetic_connector'}]}]});
 const authority=()=>new PaperclipRunnerToolAuthority(db,binding());
 async function reviewFixture(issueFields={}){
  const [reviewer,task,sourceRun,reviewRun,contract,result,assessment,decision,card]=Array.from({length:9},()=>randomUUID());
  const taskProject=issueFields.projectId??project;
  const nativeFunding={version:1,role:'reviewer',projectIds:[taskProject],issueIds:[task]};
  await db.insert(agents).values({id:reviewer,companyId:co,name:'Synthetic independent reviewer',role:'general',status:'idle',adapterType:'paperclip_runner',adapterConfig:{...config(),nativeFunding}});
  await db.insert(issues).values({id:task,companyId:co,projectId:project,title:'Synthetic same-task native review',status:'in_review',statusVersion:1,assigneeAgentId:actor,...issueFields});
  await db.insert(completionContracts).values({id:contract,companyId:co,issueId:task,revision:1,schemaVersion:'paperclip.completion-contract.v1',policyVersion:'synthetic-v1',risk:'standard',completionAuthority:'server_arbiter',incompleteCriteriaPolicy:'preserve_non_terminal',contractJson:{},canonicalSha256:contract,createdByActorType:'system',createdByActorId:'synthetic'});
  await db.insert(heartbeatRuns).values({id:sourceRun,companyId:co,agentId:actor,nativeIssueId:task,status:'succeeded',runtimeMode:'native',completionContractId:contract});
  await db.insert(nativeRunResults).values({id:result,companyId:co,issueId:task,runId:sourceRun,completionContractId:contract,serverFingerprint:result,schemaStatus:'valid',resultJson:{},canonicalSha256:result});
  await db.insert(workAssessments).values({id:assessment,companyId:co,issueId:task,runId:sourceRun,contractId:contract,resultId:result,triggerKind:'native_result',triggerActorCompanyId:co,priorIssueStatus:'in_progress',priorStatusVersion:0,policyVersion:'synthetic-v1',assessmentJson:{},inputDigest:assessment});
  await db.insert(statusDecisions).values({id:decision,companyId:co,issueId:task,runId:sourceRun,assessmentId:assessment,decisionVersion:1,policyVersion:'synthetic-v1',fromStatus:'in_progress',toStatus:'in_review',reasonCode:'synthetic',decisionJson:{projectedStatusVersion:1},decisionDigest:decision,applicationState:'applied'});
  await db.insert(issueThreadInteractions).values({id:card,companyId:co,issueId:task,kind:'request_confirmation',status:'pending',sourceRunId:sourceRun,addresseeAgentId:reviewer,effectiveResolverPolicy:'anyone',resolverPolicyProvenance:'inherited',payload:{version:1,prompt:'Review synthetic work',target:{type:'custom',key:'native_completion_review',revisionId:decision}}});
  const nativeReview={nativeReviewInteractionId:card,nativeReviewDecisionId:decision};
  await db.insert(heartbeatRuns).values({id:reviewRun,companyId:co,agentId:reviewer,nativeIssueId:task,status:'running',runtimeMode:'native',contextSnapshot:{issueId:task,sourceRunId:sourceRun,revisionId:decision,...nativeReview}});
  await db.update(issues).set({executionRunId:reviewRun,lastStatusDecisionId:decision}).where(eq(issues.id,task));
  return{reviewer,task,sourceRun,reviewRun,decision,card,nativeReview,nativeFunding};
 }
 beforeAll(async()=>{temporary=await startEmbeddedPostgresTestDatabase('native-funding-');db=createDb(temporary.connectionString);[co,actor,project,issue,run]=Array.from({length:5},()=>randomUUID());await db.insert(companies).values({id:co,name:'Synthetic funding',issuePrefix:'FND'});await db.insert(projects).values({id:project,companyId:co,name:'Synthetic funding scope'});await db.insert(agents).values({id:actor,companyId:co,name:'Synthetic producer',role:'general',status:'idle',adapterType:'paperclip_runner',adapterConfig:config()});await db.insert(issues).values({id:issue,companyId:co,projectId:project,title:'Synthetic native producer',status:'in_progress',assigneeAgentId:actor});await db.insert(heartbeatRuns).values({id:run,companyId:co,agentId:actor,nativeIssueId:issue,status:'running',runtimeMode:'native',contextSnapshot:{issueId:issue}});await db.update(issues).set({executionRunId:run}).where(eq(issues.id,issue));admitted=new Set([...raw,'other.plugin:unrelated']);calls=[];assigned=await createAssignedMcpTools({gateway:{listToolsForNamedGateway:async()=>[...admitted].map(name=>({name,displayName:'Synthetic tool',description:'Synthetic tool only',parametersSchema:{type:'object',properties:{}},risk:'write'})),executeTool:async input=>{calls.push(input.tool);return{status:'completed',result:{synthetic:true}};}},gatewayPublicId:'synthetic',bearerToken:'synthetic',workMode:'standard'});});
 afterAll(async()=>temporary?.cleanup());
 it('advertises only four freshly admitted exact funding tools, never semantic or connector catalogs',async()=>{expect((await authority().definitions()).map(t=>t.name).sort()).toEqual(raw.map(projected).sort());});
 it('dispatch denies unknown or general tool names before assigned gateway effects',async()=>{for(const tool of['call_api','connections_search','hire_agent',projected('other.plugin:unrelated'),'paperclip_call_assigned_tool'])await expect(authority().execute({tool,callId:randomUUID(),arguments:{}})).rejects.toThrow(/native_funding_tool_denied/);expect(calls).toEqual([]);});
 it('authorized producer calls use existing assigned gateway and no lifecycle mutation',async()=>{const result=await authority().execute({tool:projected(raw[0]),callId:randomUUID(),arguments:{}});expect(result).toEqual({synthetic:true});expect(calls).toEqual([raw[0]]);});
 it('fresh catalog does not advertise a revoked assigned tool',async()=>{admitted.delete(raw[0]);try{await expect(authority().definitions()).rejects.toThrow(/native_funding_catalog_incomplete/);}finally{admitted.add(raw[0]);}});
 it('rechecks role, policy and task scope before discovery and cached-authority execution',async()=>{const a=authority();for(const update of[{role:'ceo'},{status:'paused'},{adapterConfig:{provider:'codex'}}]){await db.update(agents).set(update).where(eq(agents.id,actor));try{await expect(a.definitions()).rejects.toThrow();await expect(a.execute({tool:projected(raw[0]),callId:randomUUID(),arguments:{}})).rejects.toThrow();}finally{await db.update(agents).set({role:'general',status:'idle',adapterConfig:config()}).where(eq(agents.id,actor));}}await db.update(issues).set({projectId:null}).where(eq(issues.id,issue));try{await expect(a.definitions()).rejects.toThrow(/native_funding_scope_revoked/);}finally{await db.update(issues).set({projectId:project}).where(eq(issues.id,issue));}});
 it('reviewer funding mode requires a real native review participant rather than task-assignee reuse',async()=>{const b={...binding(),nativeFundingPolicy:{...binding().nativeFundingPolicy,role:'reviewer'}};await db.update(agents).set({adapterConfig:{...config(),nativeFunding:{...config().nativeFunding,role:'reviewer'}}}).where(eq(agents.id,actor));try{await expect(new PaperclipRunnerToolAuthority(db,b).definitions()).rejects.toThrow(/native_funding_scope_revoked/);}finally{await db.update(agents).set({adapterConfig:config()}).where(eq(agents.id,actor));}});
 it('real independent native reviewer advertises only six stock review tools and retains worker ownership',async()=>{
  const{reviewer,task,reviewRun,card,nativeReview,nativeFunding}=await reviewFixture();
  const a=new PaperclipRunnerToolAuthority(db,{companyId:co,agentId:reviewer,issueId:task,runId:reviewRun,nativeFundingPolicy:{...nativeFunding,companyId:co,agentId:reviewer},nativeReview,assignedMcpTools:assigned});
  expect((await a.definitions()).map(t=>t.name).sort()).toEqual(['get_task_context','get_task_history','list_documents','read_document','list_document_revisions','resolve_review'].sort());
  const context=await a.execute({tool:'get_task_context',callId:randomUUID(),arguments:{}});expect(context.activeTask.assigneeAgentId).toBe(actor);expect(context.assignedReview.id).toBe(card);
  await expect(a.execute({tool:projected(raw[0]),callId:randomUUID(),arguments:{}})).rejects.toThrow(/native_funding_tool_denied/);
  await db.update(agents).set({status:'paused'}).where(eq(agents.id,reviewer));await expect(a.definitions()).rejects.toThrow();
 });

 it('funding review context withholds unconfirmed plans and excluded source child material',async()=>{
  const f=await reviewFixture(),excluded=randomUUID();await db.insert(projects).values({id:excluded,companyId:co,name:'Excluded synthetic project'});
  const ownPlan=await documentService(db).upsertIssueDocument({issueId:f.task,key:'plan',title:'Unconfirmed synthetic plan',format:'markdown',body:'DO_NOT_PROJECT_UNCONFIRMED',baseRevisionId:null,createdByAgentId:actor});
  await db.update(heartbeatRuns).set({contextSnapshot:{issueId:f.task,sourceRunId:f.sourceRun,revisionId:f.decision,...f.nativeReview,planReviewInteraction:{acceptedTargetRevision:{revisionId:ownPlan.document.latestRevisionId}}}}).where(eq(heartbeatRuns.id,f.reviewRun));
  const a=new PaperclipRunnerToolAuthority(db,{companyId:co,agentId:f.reviewer,issueId:f.task,runId:f.reviewRun,nativeFundingPolicy:{...f.nativeFunding,companyId:co,agentId:f.reviewer},nativeReview:f.nativeReview,assignedMcpTools:assigned});
  for(const fields of[{projectId:excluded},{projectId:project,hiddenAt:new Date()},{projectId:project}])await db.insert(issues).values({id:randomUUID(),companyId:co,parentId:f.task,title:'DO_NOT_PROJECT_CHILD',description:'Synthetic excluded child content',status:'done',...fields});
  const reviewed=await reviewFixture({parentId:f.task,projectId:excluded});await db.update(issueThreadInteractions).set({status:'accepted',resolvedByAgentId:reviewed.reviewer,resolvedByRunId:reviewed.reviewRun,resolvedAt:new Date()}).where(eq(issueThreadInteractions.id,reviewed.card));await db.update(issues).set({status:'done',executionRunId:null}).where(eq(issues.id,reviewed.task));await db.update(heartbeatRuns).set({status:'succeeded'}).where(eq(heartbeatRuns.id,reviewed.reviewRun));
  const contexts=[];
  for(const fields of[{projectId:project,hiddenAt:new Date()},{projectId:excluded},{projectId:project}]){
   const source=randomUUID(),originRun=randomUUID();await db.insert(issues).values({id:source,companyId:co,conversationAgentId:actor,conversationUserId:'synthetic-'+randomUUID(),conversationState:'waiting',assigneeAgentId:actor,status:'in_progress',title:'DO_NOT_PROJECT_SOURCE',...fields});
   const plan=await documentService(db).upsertIssueDocument({issueId:source,key:'plan',title:'Excluded source plan',format:'markdown',body:'DO_NOT_PROJECT_SOURCE_PLAN',baseRevisionId:null,createdByAgentId:actor});
   await db.insert(issueThreadInteractions).values({id:randomUUID(),companyId:co,issueId:source,kind:'request_confirmation',status:'accepted',payload:{version:1,prompt:'Synthetic approval',target:{type:'issue_document',issueId:source,key:'plan',revisionId:plan.document.latestRevisionId}},resolvedAt:new Date('2026-01-01T00:00:00Z')});
   await db.insert(heartbeatRuns).values({id:originRun,companyId:co,agentId:actor,nativeIssueId:source,status:'succeeded',runtimeMode:'native',contextSnapshot:{issueId:source}});await db.update(issues).set({originRunId:originRun}).where(eq(issues.id,f.task));
   contexts.push(await a.execute({tool:'get_task_context',callId:randomUUID(),arguments:{}}));
  }
  for(const context of contexts){expect(context.acceptedPlan).toBeNull();expect(context.sourcePlanApproval).toBeNull();expect(context.childReviewOutcomes).toEqual([]);expect(context.childTasks).toEqual([]);expect(context.childTasksTruncated).toBe(false);expect(JSON.stringify(context)).not.toContain('DO_NOT_PROJECT');}
 });

});
